contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public test entry
    // putLock, putAmount, collectAmount are arbitrary inputs; this function may send Ether for Put
    function run(uint putLock, uint putAmount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (putAmount)); require(putAmount <= 1000000000000000000000000000000);
        // ensure this contract has enough balance to send to c for Put
        require(address(this).balance >= putAmount);

        // Read recorded balance before any operations
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this)); if (__ESBMC_reverted()) return;

        // Perform a Put (may revert). This is a top-level state-changing call.
        bool putReverted;
        c.Put{value: putAmount}(putLock); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            putReverted = true;
        } else {
            putReverted = false;
        }

        // Read recorded balance after Put (or after failed Put)
        (uint midUnlock, uint midBal) = c.Acc(address(this)); if (__ESBMC_reverted()) return;

        // Attempt Collect and capture whether it reverted
        bool collectReverted;
        c.Collect(collectAmount); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            collectReverted = true;
        } else {
            collectReverted = false;
        }

        // Read recorded balance after Collect (or after failed Collect)
        (uint afterUnlock, uint afterBal) = c.Acc(address(this)); if (__ESBMC_reverted()) return;

        // General invariant: if Collect did not revert then recorded balance did not increase compared to immediately before Collect
        // We use midBal as the balance immediately before Collect (i.e., after Put attempt).
        assert(collectReverted || afterBal <= midBal);
    }

    // Allow receiving Ether so the test contract can be funded externally
    receive() external payable {}
}

